ORDER = ['company','sectors','clients','projects','sourcing','logistics','suppliers','contact']


def filename(c,key):
    if key == 'home': return c['home']
    if key == 'catalog': return c['prefix']+'catalogo.html'
    if key == 'legal': return c['prefix']+'legale.html'
    m={'company':'azienda.html','sectors':'settori.html','clients':'clienti.html','projects':'progetti.html','sourcing':'sourcing.html','logistics':'logistica.html','suppliers':'fornitori.html','contact':'contatti.html'}
    return c['prefix']+m[key]


def language_links(key):
    return ' '.join(f'<a href="{filename(DATA[l],key)}">{l.upper()}</a>' for l in ['it','de','en','al'])


def head(c,title,desc):
    return f'''<!doctype html><html lang="{c['html_lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | INTERXTRADE™</title><meta name="description" content="{escape(desc)}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css"><link rel="icon" href="https://shop.interxtrade.eu/favicon.svg"></head><body>'''


def header(c,key):
    nav=''.join(f'<a href="{filename(c,k)}">{c["nav"][k]}</a>' for k in ORDER)
    return f'''<div class="topbar"><div class="wrap"><span>{c['top']}</span><div class="langs">{language_links(key)}</div></div></div><header><div class="wrap head"><a class="brand" href="{c['home']}"><img src="{LOGO}" alt="INTERXTRADE"></a><button class="menu-toggle" aria-expanded="false" aria-label="Menu">☰</button><nav class="nav">{nav}<a class="shop" href="{c['shop']}">{c['shop_label']}</a></nav></div></header>'''


def footer(c):
    return f'''<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="footer-brand" href="{c['home']}"><img src="{LOGO}" alt="INTERXTRADE"></a><p>{c['footer1']}<br>{c['footer2']}</p></div><div><h4>INTERXTRADE</h4><p><a href="{filename(c,'company')}">{c['nav']['company']}</a><br><a href="{filename(c,'sectors')}">{c['nav']['sectors']}</a><br><a href="{filename(c,'suppliers')}">{c['nav']['suppliers']}</a><br><a href="{filename(c,'legal')}">Legal / Privacy</a></p></div><div><h4>CONTACT</h4><p><a href="mailto:{EMAIL}">{EMAIL}</a><br><a href="tel:+393313213312">{PHONE}</a><br>Via Rodolfo Berretta 20<br>56021 Cascina (PI) · Italia</p></div></div><div class="copy">© 2026 INTERXTRADE™ · EUROPA INFISSI S.R.L.S. · P.IVA 02433990500 · REA PI-206715</div></div></footer><script src="site.js"></script></body></html>'''


def cards(items):
    return '<div class="grid">'+''.join(f'<article class="card"><div class="num">{i:02d}</div><h3>{escape(t)}</h3><p>{escape(p)}</p></article>' for i,(t,p) in enumerate(items,1))+'</div>'


def home(c):
    h,p,b1,b2=c['homecopy']
    homecards='<div class="grid">'+''.join(f'<article class="card"><h3>{escape(t)}</h3><p>{escape(p)}</p><a href="{filename(c,k)}">{escape(t)} →</a></article>' for t,p,k in c['home_cards'])+'</div>'
    stats='<section class="stats"><div class="wrap">'+''.join(f'<div class="stat"><b>{escape(a)}</b><span>{escape(b)}</span></div>' for a,b in c['stats'])+'</div></section>'
    mk=''.join(f'<span>{escape(x)}</span>' for x in c['markets'])
    body=f'''{head(c,h,p)}{header(c,'home')}<section class="hero"><div class="wrap"><div class="eyebrow">INTERXTRADE · B2B</div><h1>{escape(h)}</h1><p>{escape(p)}</p><div class="actions"><a class="btn primary" href="{c['shop']}">{escape(b1)}</a><a class="btn" href="{c['rfq']}">{escape(b2)}</a></div></div></section><section class="intro"><div class="wrap split"><div class="eyebrow">INTERXTRADE</div><div><h2>{escape(c['intro'][0])}</h2><p>{escape(c['intro'][1])}</p><div class="marketline">{mk}</div></div></div></section>{stats}<section class="section"><div class="wrap"><div class="section-head"><div class="eyebrow">B2B NETWORK</div><h2>{escape(c['market'])}</h2></div>{homecards}</div></section><section class="cta-band"><div class="wrap"><h2>{escape(c['pages']['projects'][1])}</h2><a class="btn primary" href="{c['project_shop']}">{escape(c['cta_project'])}</a></div></section>{footer(c)}'''
    return body


def standard_page(c,key):
    label,title,intro,items=c['pages'][key]
    inner=cards(items) if items else ''
    if key=='company':
        mk=''.join(f'<span>{escape(x)}</span>' for x in c['markets'])
        extra=f'<section class="section sand"><div class="wrap split"><div><div class="eyebrow">EUROPE</div><h2>{escape(c["market"])}</h2></div><div><p>{escape(c["intro"][1])}</p><div class="marketline">{mk}</div></div></div></section>'
    elif key=='projects':
        extra=f'<section class="cta-band"><div class="wrap"><h2>{escape(title)}</h2><a class="btn primary" href="{c["project_shop"]}">{escape(c["cta_project"])}</a></div></section>'
    elif key in ('sourcing','logistics'):
        extra=f'<section class="cta-band"><div class="wrap"><h2>{escape(c["homecopy"][0])}</h2><a class="btn primary" href="{c["rfq"]}">{escape(c["cta_quote"])}</a></div></section>'
    elif key=='suppliers':
        extra=f'<section class="cta-band"><div class="wrap"><h2>{escape(title)}</h2><a class="btn primary" href="mailto:{EMAIL}">{escape(c["nav"]["contact"])}</a></div></section>'
    else: extra=''
    return f'''{head(c,title,intro)}{header(c,key)}<section class="pagehero"><div class="wrap"><div class="eyebrow">{escape(label)}</div><h1>{escape(title)}</h1><p>{escape(intro)}</p></div></section><section class="section"><div class="wrap">{inner}</div></section>{extra}{footer(c)}'''


def contact_page(c):
    label,title,intro,_=c['pages']['contact']
    return f'''{head(c,title,intro)}{header(c,'contact')}<section class="pagehero"><div class="wrap"><div class="eyebrow">{escape(label)}</div><h1>{escape(title)}</h1><p>{escape(intro)}</p></div></section><section class="section"><div class="wrap"><div class="contact-grid"><div class="contact-card"><h3>E-mail</h3><p><a href="mailto:{EMAIL}">{EMAIL}</a></p></div><div class="contact-card"><h3>Phone</h3><p><a href="tel:+393313213312">{PHONE}</a></p></div><div class="contact-card"><h3>B2B Shop</h3><p><a href="{c['shop']}">{escape(c['shop_label'])} →</a></p></div></div><div class="actions"><a class="btn blue" href="{c['rfq']}">{escape(c['cta_quote'])}</a><a class="btn dark" href="{c['project_shop']}">{escape(c['cta_project'])}</a></div></div></section>{footer(c)}'''


def catalog_page(c):
    label,title,intro,_=c['pages']['catalog']
    return f'''{head(c,title,intro)}{header(c,'catalog')}<section class="pagehero"><div class="wrap"><div class="eyebrow">{escape(label)}</div><h1>{escape(title)}</h1><p>{escape(intro)}</p><div class="actions"><a class="btn blue" href="{c['shop']}">{escape(c['shop_label'])} →</a><a class="btn dark" href="{c['rfq']}">{escape(c['cta_quote'])}</a></div></div></section><section class="section soft"><div class="wrap"><div class="notice">{escape(c['legal_note'])}</div></div></section>{footer(c)}'''


